"""The multi-symbol replay session: orchestration only.

:class:`EventReplayer` owns the session state (per-symbol books, sequence
counters, the global idempotency log, the matching configuration) and the
per-event pipeline: envelope validation, payload normalization, structural
validation, global idempotency, per-symbol sequencing and the single
deterministic commit. Everything type-specific — schemas, inline key sets,
business handlers, price-limit pre-checks — comes from the event-kind
registry, so this module never switches on an event type itself.
"""

from __future__ import annotations

from ..engine import DUPLICATE_EVENT_ID
from .constants import (
    DEFAULT_CONFIG,
    DUPLICATE,
    EVENT_ID_CONFLICT,
    INVALID_EVENT,
    OUT_OF_ORDER,
    REJECTED,
    SEQUENCE_GAP,
    SUPPORTED_TYPES,
    _ENVELOPE_KEYS,
)
from .handlers import price_limit_rejection
from .registry import KINDS, kind_for
from .serialization import _digest, canonical_json
from .state import (
    _Applied,
    _CommitContext,
    _SymbolState,
    invalid_result,
)
from .validation import _validate_config, _valid_timestamp


class EventReplayer:
    """Stateful, resumable multi-symbol replay session.

    One session binds together the per-symbol books, per-symbol sequence
    counters, the global idempotency log and the matching configuration.
    Instances are normally obtained from :func:`replay_events` or restored via
    :func:`restore_replayer`; they are not thread safe on purpose.
    """

    def __init__(self, config: dict[str, object] | None = None) -> None:
        if config is not None and not isinstance(config, dict):
            raise TypeError("config must be a JSON object or None")
        self.config: dict[str, object] = dict(DEFAULT_CONFIG if config is None else config)
        _validate_config(self.config)
        # Static per-security price bounds (closed interval), parsed from the
        # validated config. They seed each security's *active* interval (and
        # a legacy snapshot's restored one); accepted PRICE_LIMIT_UPDATE
        # events then replace the active interval per security. Securities
        # without an entry start unlimited.
        raw_limits = self.config.get("price_limits") or {}
        self.price_limits: dict[str, tuple[int, int]] = {
            symbol: (bounds["lower"], bounds["upper"])
            for symbol, bounds in raw_limits.items()
        }
        self.config_digest = _digest(self.config)
        self._symbols: dict[str, _SymbolState] = {}
        # Global index of every accepted eventId: eventId -> (symbol, content).
        self._events: dict[str, tuple[str, str]] = {}

    # -- book helpers -------------------------------------------------------

    def book(self, symbol: str) -> tuple[list[dict[str, int]], list[dict[str, int]]]:
        """The final ``(bids, asks)`` aggregates for one security."""
        state = self._symbols.get(symbol)
        if state is None:
            return [], []
        return state.engine.snapshot()

    # -- main entry ---------------------------------------------------------

    def submit(self, events: list[dict[str, object]]) -> list[dict[str, object]]:
        """Apply an ordered list of event objects, one result per event."""
        return [self._submit_one(event) for event in events]

    def _submit_one(self, event: object) -> dict[str, object]:
        # ---- envelope validation (nothing is consumed on failure) --------
        if not isinstance(event, dict):
            return invalid_result(event)
        event_id = event.get("event_id")
        symbol = event.get("symbol")
        sequence = event.get("sequence")
        timestamp = event.get("timestamp")
        valid_envelope_ids = (
            isinstance(event_id, str)
            and event_id != ""
            and isinstance(symbol, str)
            and symbol != ""
            and isinstance(sequence, int)
            and not isinstance(sequence, bool)
            and sequence > 0
        )
        if not valid_envelope_ids:
            # The symbol cannot be trusted yet, so no book is echoed and no
            # symbol state is created.
            return invalid_result(event)

        def reject_envelope(code: str = INVALID_EVENT) -> dict[str, object]:
            # A structurally invalid event for a recognizable symbol echoes the
            # untouched book but never mutates or registers anything.
            return invalid_result(event, code, state=self._symbols.get(symbol))

        if "timestamp" in event and not _valid_timestamp(timestamp):
            return reject_envelope()

        # The baseline payload is either nested under "event" or carried
        # inline alongside the envelope fields.
        if "event" in event:
            nested = event["event"]
            envelope_keys = _ENVELOPE_KEYS | {"event"}
            if not isinstance(nested, dict):
                return reject_envelope()
            payload: dict[str, object] = nested
            # The wrapper may only carry envelope fields plus the payload.
            if not set(event) <= envelope_keys:
                return reject_envelope()
        else:
            # The inline form may carry envelope fields plus exactly the fields
            # of its own payload kind.
            inline_kind = kind_for(event.get("type"))
            if inline_kind is None or not set(event) <= (
                _ENVELOPE_KEYS | inline_kind.payload_keys
            ):
                return reject_envelope()
            # Keep event_id/type (payload fields); strip only symbol,
            # sequence and timestamp, which are envelope-only.
            payload = {
                key: value
                for key, value in event.items()
                if key not in ("symbol", "sequence", "timestamp")
            }
        event_type = payload.get("type")
        if not isinstance(event_type, str) or event_type not in SUPPORTED_TYPES:
            return reject_envelope()
        # Validate the full payload schema up front, so malformed content is
        # classified INVALID_EVENT and reaches neither ordering nor the book.
        # The wrapper and the payload must identify the same event.
        if payload.get("event_id") != event_id:
            return reject_envelope()
        kind = KINDS[event_type]
        if kind.schema_error(payload) is not None:
            return reject_envelope()

        # A symbol state is created only once the event is fully well formed;
        # failures that precede dispatch must not register an empty book.
        state = self._symbols.get(symbol)
        known_symbol = state is not None
        if state is None:
            state = _SymbolState()
            # The active interval starts at the static configuration; an
            # accepted PRICE_LIMIT_UPDATE replaces it from then on.
            state.price_limits = self.price_limits.get(symbol)

        # ---- global idempotency (checked before sequencing) --------------
        # A retried delivery carries its original, now-stale sequence; it must
        # still be recognized as a duplicate rather than as out-of-order.
        content = canonical_json(payload).decode("utf-8")
        prior = self._events.get(event_id)
        if prior is not None:
            prior_symbol, prior_content = prior
            if prior_symbol == symbol and prior_content == content:
                bids, asks = state.engine.snapshot()
                return {
                    "event_id": event_id,
                    "symbol": symbol,
                    "sequence": sequence,
                    "status": DUPLICATE,
                    "trades": [],
                    "book_changes": {"bids": [], "asks": []},
                    "bids": bids,
                    "asks": asks,
                }
            # Same id, different symbol or different normalized content: a
            # conflict consumes neither sequence nor book state, so the
            # correct next event can follow immediately.
            return invalid_result(
                event, EVENT_ID_CONFLICT,
                expected_sequence=state.last_sequence + 1 if known_symbol else None,
                state=state if known_symbol else None,
            )

        # ---- per-symbol strict sequence ordering -------------------------
        expected = state.last_sequence + 1
        if sequence < expected or sequence > expected:
            code = OUT_OF_ORDER if sequence < expected else SEQUENCE_GAP
            return invalid_result(
                event, code, expected_sequence=expected,
                state=state if known_symbol else None,
            )

        # ---- committed application ---------------------------------------
        # From here on the event is structurally valid and in sequence: it is
        # a committed application. The context owns the single symbol
        # registration, the deterministic id/sequence commit, the post-event
        # book echo and the response assembly; the registered kind describes
        # everything type-specific.
        ctx = _CommitContext(
            self._symbols, self._events,
            event_id, event_type, symbol, sequence, content, state, known_symbol,
        )
        ctx.register_symbol()

        # A derived child id (``plan_id#slice``) is reserved from plan start;
        # it occupies both the order-id and event-id role of the future child,
        # so no external event — baseline or parent-order command — may reuse
        # it as an event id.
        if event_id in state.plan_index:
            # Committed like every baseline business rejection: the well-formed
            # event occupies its id and the sequence, but nothing else moves.
            return ctx.finish(_Applied(REJECTED, code=DUPLICATE_EVENT_ID))

        # ---- active per-security price limits ---------------------------
        # Enforced after the envelope, idempotency, sequence and identifier
        # conflict checks, and strictly before matching or any state change.
        # The identifier clashes the baseline engine would reach first (a
        # reused order id, a replace against a missing order, a duplicate plan
        # or a clashing derived id) keep their rejection-code precedence; a
        # price breach is only reported when none applies. The interval tested
        # here is the security's *active* one: the static config interval as
        # last replaced by any accepted PRICE_LIMIT_UPDATE.
        if kind.price_limit_checked:
            price_rejection = price_limit_rejection(payload, event_type, state)
            if price_rejection is not None:
                # A committed business rejection: it occupies the event id and
                # advances the symbol sequence, but performs no matching, leaves
                # no order or plan behind and spends no trade id. Baseline event
                # ids also occupy the per-symbol engine journal, exactly as an
                # engine-side business rejection would; plan commands live solely
                # in the replay log.
                return ctx.finish(_Applied(
                    REJECTED, code=price_rejection,
                    occupy_engine_id=not kind.replay_only,
                ))

        # Only book-moving kinds capture the visible levels up front, so the
        # level-diff reports drained levels and iceberg replenishment.
        if kind.captures_book:
            ctx.capture_book()
        return ctx.finish(kind.handler(self, ctx, payload))

"""Single-instrument order book with price-time priority matching.

The engine is deterministic: given the same sequence of event objects it
produces identical results, trade identifiers and book snapshots.
Rejected events never mutate engine state.
"""

from __future__ import annotations

import copy
import json
from collections import deque

ADD = "ADD"
CANCEL = "CANCEL"
REPLACE = "REPLACE"
EXECUTION_REPORT = "EXECUTION_REPORT"
ACCOUNT_REPORT = "ACCOUNT_REPORT"
DAY_END_RECONCILIATION = "DAY_END_RECONCILIATION"
IMPACT_REPORT = "IMPACT_REPORT"
BUY = "BUY"
SELL = "SELL"
LIMIT = "LIMIT"
MARKET = "MARKET"
ICEBERG = "ICEBERG"

GTC = "GTC"
IOC = "IOC"
FOK = "FOK"

FILLED = "FILLED"
RESTING = "RESTING"
REPLACED = "REPLACED"
PARTIALLY_FILLED_RESTING = "PARTIALLY_FILLED_RESTING"
PARTIALLY_FILLED_CANCELLED = "PARTIALLY_FILLED_CANCELLED"
PARTIALLY_FILLED_SELF_TRADE_PREVENTED = "PARTIALLY_FILLED_SELF_TRADE_PREVENTED"
UNFILLED_CANCELLED = "UNFILLED_CANCELLED"
SELF_TRADE_PREVENTED = "SELF_TRADE_PREVENTED"
CANCELLED = "CANCELLED"
REJECTED = "REJECTED"
REPORTED = "REPORTED"
RECONCILED = "RECONCILED"
BREAKS_FOUND = "BREAKS_FOUND"

MAKER = "MAKER"
TAKER = "TAKER"

MISSING_ACTUAL = "MISSING_ACTUAL"
MISSING_EXPECTED = "MISSING_EXPECTED"
FIELD_MISMATCH = "FIELD_MISMATCH"

INVALID_JSON = "INVALID_JSON"
INVALID_SCHEMA = "INVALID_SCHEMA"
DUPLICATE_EVENT_ID = "DUPLICATE_EVENT_ID"
DUPLICATE_ORDER_ID = "DUPLICATE_ORDER_ID"
UNKNOWN_ORDER = "UNKNOWN_ORDER"
UNKNOWN_ACCOUNT = "UNKNOWN_ACCOUNT"

_ALL_KEYS = frozenset(
    {"event_id", "type", "order_id", "side", "order_type", "quantity", "price",
     "time_in_force", "display_quantity", "account_id"}
)
_CANCEL_KEYS = frozenset({"event_id", "type", "order_id"})
_REPORT_KEYS = frozenset({"event_id", "type", "order_id", "benchmark_price"})
_IMPACT_KEYS = frozenset(
    {"event_id", "type", "side", "quantity", "benchmark_price"}
)
_ACCOUNT_REPORT_KEYS = frozenset({"event_id", "type", "account_id", "mark_price"})
_RECONCILIATION_KEYS = frozenset(
    {"event_id", "type", "expected_trades", "expected_accounts"}
)
_EXPECTED_TRADE_KEYS = frozenset(
    {"trade_id", "maker_order_id", "taker_order_id", "price", "quantity"}
)
_EXPECTED_ACCOUNT_KEYS = frozenset({"account_id", "net_position", "cash_balance"})
_REQUIRED_ADD_KEYS = frozenset({"event_id", "type", "order_id", "side", "order_type", "quantity"})
_REQUIRED_REPLACE_KEYS = frozenset({"event_id", "type", "order_id", "quantity", "price"})
_ALLOWED_REPLACE_KEYS = _REQUIRED_REPLACE_KEYS | {"display_quantity"}


def _is_positive_int(value: object) -> bool:
    # ``bool`` is a subclass of ``int`` and must not be accepted.
    return isinstance(value, int) and not isinstance(value, bool) and value > 0


def _is_non_empty_str(value: object) -> bool:
    return isinstance(value, str) and value != ""


def _is_int(value: object) -> bool:
    # Any JSON integer stays exact; booleans are not integers.
    return isinstance(value, int) and not isinstance(value, bool)


class Engine:
    """Stateful replay engine processing events in arrival order."""

    def __init__(self, _state: dict[str, object] | None = None) -> None:
        if _state is not None:
            # Internal fast path used when restoring an authoritative snapshot:
            # the state dict is owned by the caller's snapshot machinery, not by
            # user input, so it can be adopted verbatim without copying.
            self._event_ids: set[str] = _state["event_ids"]
            self._order_ids: set[str] = _state["order_ids"]
            self._reserved_order_ids: set[str] = _state["reserved_order_ids"]
            self._orders: dict[str, dict[str, object]] = _state["orders"]
            self._bids: dict[int, deque[str]] = _state["bids"]
            self._asks: dict[int, deque[str]] = _state["asks"]
            self._bid_totals: dict[int, int] = _state["bid_totals"]
            self._ask_totals: dict[int, int] = _state["ask_totals"]
            self._next_trade_id: int = _state["next_trade_id"]
            self._accounts: set[str] = _state["accounts"]
            self._trade_log: list[dict[str, object]] = _state["trade_log"]
            return
        self._event_ids = set()
        self._order_ids = set()
        # Identifiers reserved by future parent-order slices: they block reuse
        # through ADD exactly like spent order ids, but have no order record
        # until their slice is released. Always empty on the baseline entry
        # points.
        self._reserved_order_ids = set()
        self._orders = {}
        self._bids = {}
        self._asks = {}
        self._bid_totals = {}
        self._ask_totals = {}
        self._next_trade_id = 1
        # Accounts seen on any accepted ADD, however the orders ended up.
        self._accounts = set()
        # Every trade ever executed, in trade_id order, tagged with the id of
        # the event that produced it. Execution reports are built from this
        # journal; matching output keeps its historical shape.
        self._trade_log = []

    def handle_line(self, line: str) -> tuple[str | None, str, str | None, list[dict[str, object]]]:
        """Process one input line (without line terminator).

        Returns ``(event_id, result, reason, trades)`` where ``event_id`` is
        the event id when it can be obtained as a string, otherwise ``None``,
        and ``reason`` is set only for rejected events.
        """
        event_id, result, reason, trades, _stp = self.handle_line_full(line)
        return event_id, result, reason, trades

    def handle_line_full(
        self, line: str
    ) -> tuple[str | None, str, str | None, list[dict[str, object]], dict[str, object] | None]:
        """Like :meth:`handle_line`, additionally returning the self-trade
        prevention descriptor (``None`` for every other result)."""
        event_id, result, reason, trades, stp, _analysis = self.handle_line_extended(line)
        return event_id, result, reason, trades, stp

    def handle_line_extended(
        self, line: str
    ) -> tuple[
        str | None, str, str | None,
        list[dict[str, object]], dict[str, object] | None, dict[str, object] | None,
    ]:
        """Like :meth:`handle_line_full`, additionally returning the execution
        analysis of an ``EXECUTION_REPORT`` query (``None`` otherwise)."""
        event_id, result, reason, trades, stp, analysis, _position = (
            self.handle_line_position(line)
        )
        return event_id, result, reason, trades, stp, analysis

    def handle_line_position(
        self, line: str
    ) -> tuple[
        str | None, str, str | None,
        list[dict[str, object]], dict[str, object] | None,
        dict[str, object] | None, dict[str, object] | None,
    ]:
        """Like :meth:`handle_line_extended`, additionally returning the
        position analysis of an ``ACCOUNT_REPORT`` query (``None`` otherwise)."""
        event_id, result, reason, trades, stp, analysis, position, _recon = (
            self.handle_line_reconciliation(line)
        )
        return event_id, result, reason, trades, stp, analysis, position

    def handle_line_reconciliation(
        self, line: str
    ) -> tuple[
        str | None, str, str | None,
        list[dict[str, object]], dict[str, object] | None,
        dict[str, object] | None, dict[str, object] | None,
        dict[str, object] | None,
    ]:
        """Like :meth:`handle_line_position`, additionally returning the
        reconciliation report of a ``DAY_END_RECONCILIATION`` query
        (``None`` otherwise)."""
        event_id, result, reason, trades, stp, analysis, position, recon, _impact = (
            self.handle_line_impact(line)
        )
        return event_id, result, reason, trades, stp, analysis, position, recon

    def handle_line_impact(
        self, line: str
    ) -> tuple[
        str | None, str, str | None,
        list[dict[str, object]], dict[str, object] | None,
        dict[str, object] | None, dict[str, object] | None,
        dict[str, object] | None, dict[str, object] | None,
    ]:
        """Like :meth:`handle_line_reconciliation`, additionally returning the
        impact analysis of an ``IMPACT_REPORT`` what-if query (``None``
        otherwise)."""
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            return None, REJECTED, INVALID_JSON, [], None, None, None, None, None
        return self.handle_object_impact(obj)

    def handle_object(
        self, obj: object
    ) -> tuple[str | None, str, str | None, list[dict[str, object]], dict[str, object] | None]:
        event_id, result, reason, trades, stp, _analysis = self.handle_object_extended(obj)
        return event_id, result, reason, trades, stp

    def handle_object_extended(
        self, obj: object
    ) -> tuple[
        str | None, str, str | None,
        list[dict[str, object]], dict[str, object] | None, dict[str, object] | None,
    ]:
        event_id, result, reason, trades, stp, analysis, _position = (
            self.handle_object_position(obj)
        )
        return event_id, result, reason, trades, stp, analysis

    def handle_object_position(
        self, obj: object
    ) -> tuple[
        str | None, str, str | None,
        list[dict[str, object]], dict[str, object] | None,
        dict[str, object] | None, dict[str, object] | None,
    ]:
        event_id, result, reason, trades, stp, analysis, position, _recon = (
            self.handle_object_reconciliation(obj)
        )
        return event_id, result, reason, trades, stp, analysis, position

    def handle_object_reconciliation(
        self, obj: object
    ) -> tuple[
        str | None, str, str | None,
        list[dict[str, object]], dict[str, object] | None,
        dict[str, object] | None, dict[str, object] | None,
        dict[str, object] | None,
    ]:
        event_id, result, reason, trades, stp, analysis, position, recon, _impact = (
            self.handle_object_impact(obj)
        )
        return event_id, result, reason, trades, stp, analysis, position, recon

    def handle_object_impact(
        self, obj: object
    ) -> tuple[
        str | None, str, str | None,
        list[dict[str, object]], dict[str, object] | None,
        dict[str, object] | None, dict[str, object] | None,
        dict[str, object] | None, dict[str, object] | None,
    ]:
        """Like :meth:`handle_object_reconciliation`, additionally returning
        the impact analysis of an ``IMPACT_REPORT`` query (``None``
        otherwise)."""
        if not isinstance(obj, dict):
            return None, REJECTED, INVALID_SCHEMA, [], None, None, None, None, None

        event_id = obj.get("event_id")
        event_id_out = event_id if isinstance(event_id, str) else None

        schema_error = self._schema_error(obj)
        if schema_error is not None:
            return event_id_out, REJECTED, schema_error, [], None, None, None, None, None

        if event_id in self._event_ids:
            return event_id, REJECTED, DUPLICATE_EVENT_ID, [], None, None, None, None, None
        if obj["type"] == REPLACE and "display_quantity" in obj:
            target = self._orders.get(obj["order_id"])
            if (
                target is not None
                and target["status"] == RESTING
                and "display_quantity" not in target
            ):
                # Only an iceberg target may be replaced with a display slice;
                # like every schema error this consumes no event id.
                return event_id, REJECTED, INVALID_SCHEMA, [], None, None, None, None, None
        # The event is well formed, so its id occupies the stream from here,
        # even if a later business rule rejects it.
        self._event_ids.add(event_id)

        if obj["type"] == CANCEL:
            event_id, result, reason, trades = self._cancel(event_id, obj["order_id"])
            return event_id, result, reason, trades, None, None, None, None, None
        if obj["type"] == REPLACE:
            event_id, result, reason, trades, stp = self._replace(event_id, obj)
            return event_id, result, reason, trades, stp, None, None, None, None
        if obj["type"] == EXECUTION_REPORT:
            event_id, result, reason, trades, stp, analysis = self._execution_report(
                event_id, obj
            )
            return event_id, result, reason, trades, stp, analysis, None, None, None
        if obj["type"] == IMPACT_REPORT:
            event_id, result, reason, trades, impact = self._impact_report(
                event_id, obj
            )
            return event_id, result, reason, trades, None, None, None, None, impact
        if obj["type"] == ACCOUNT_REPORT:
            event_id, result, reason, trades, stp, analysis, position = (
                self._account_report(event_id, obj)
            )
            return event_id, result, reason, trades, stp, analysis, position, None, None
        if obj["type"] == DAY_END_RECONCILIATION:
            return (*self._day_end_reconciliation(event_id, obj), None)
        event_id, result, reason, trades, stp = self._add(event_id, obj)
        return event_id, result, reason, trades, stp, None, None, None, None

    @staticmethod
    def _schema_error(obj: dict[str, object]) -> str | None:
        keys = set(obj)
        event_type = obj.get("type")
        if event_type == EXECUTION_REPORT:
            # A pure query: exactly the four fields, string identifiers and a
            # positive integer benchmark (booleans are not integers).
            if keys != _REPORT_KEYS:
                return INVALID_SCHEMA
            if not isinstance(obj.get("event_id"), str):
                return INVALID_SCHEMA
            if not isinstance(obj.get("order_id"), str):
                return INVALID_SCHEMA
            if not _is_positive_int(obj.get("benchmark_price")):
                return INVALID_SCHEMA
            return None
        if event_type == IMPACT_REPORT:
            # A pure read-only what-if query: exactly the five fields, a string
            # event id, a BUY/SELL side and positive integer quantity and
            # benchmark (booleans are not integers).
            if keys != _IMPACT_KEYS:
                return INVALID_SCHEMA
            if not isinstance(obj.get("event_id"), str):
                return INVALID_SCHEMA
            if obj.get("side") not in (BUY, SELL):
                return INVALID_SCHEMA
            if not _is_positive_int(obj.get("quantity")):
                return INVALID_SCHEMA
            if not _is_positive_int(obj.get("benchmark_price")):
                return INVALID_SCHEMA
            return None
        if event_type == ACCOUNT_REPORT:
            # A pure query: exactly the four fields, non-empty string
            # identifiers and a positive integer mark (booleans are not
            # integers).
            if keys != _ACCOUNT_REPORT_KEYS:
                return INVALID_SCHEMA
            if not _is_non_empty_str(obj.get("event_id")):
                return INVALID_SCHEMA
            if not _is_non_empty_str(obj.get("account_id")):
                return INVALID_SCHEMA
            if not _is_positive_int(obj.get("mark_price")):
                return INVALID_SCHEMA
            return None
        if event_type == DAY_END_RECONCILIATION:
            # A pure read-only query: exactly the four fields, a non-empty
            # string event id and the two external record arrays. Identifiers
            # must be unique within their array and booleans are not integers.
            if keys != _RECONCILIATION_KEYS:
                return INVALID_SCHEMA
            if not _is_non_empty_str(obj.get("event_id")):
                return INVALID_SCHEMA
            expected_trades = obj.get("expected_trades")
            expected_accounts = obj.get("expected_accounts")
            if not isinstance(expected_trades, list):
                return INVALID_SCHEMA
            if not isinstance(expected_accounts, list):
                return INVALID_SCHEMA
            seen_trade_ids: set[int] = set()
            for item in expected_trades:
                if not isinstance(item, dict) or set(item) != _EXPECTED_TRADE_KEYS:
                    return INVALID_SCHEMA
                trade_id = item.get("trade_id")
                if not _is_positive_int(trade_id) or trade_id in seen_trade_ids:
                    return INVALID_SCHEMA
                seen_trade_ids.add(trade_id)
                if not _is_non_empty_str(item.get("maker_order_id")):
                    return INVALID_SCHEMA
                if not _is_non_empty_str(item.get("taker_order_id")):
                    return INVALID_SCHEMA
                if not _is_positive_int(item.get("price")):
                    return INVALID_SCHEMA
                if not _is_positive_int(item.get("quantity")):
                    return INVALID_SCHEMA
            seen_account_ids: set[str] = set()
            for item in expected_accounts:
                if not isinstance(item, dict) or set(item) != _EXPECTED_ACCOUNT_KEYS:
                    return INVALID_SCHEMA
                account_id = item.get("account_id")
                if not _is_non_empty_str(account_id) or account_id in seen_account_ids:
                    return INVALID_SCHEMA
                seen_account_ids.add(account_id)
                if not _is_int(item.get("net_position")):
                    return INVALID_SCHEMA
                if not _is_int(item.get("cash_balance")):
                    return INVALID_SCHEMA
            return None
        if not keys <= _ALL_KEYS:
            return INVALID_SCHEMA
        if not isinstance(obj.get("event_id"), str):
            return INVALID_SCHEMA

        if event_type == CANCEL:
            if keys != _CANCEL_KEYS:
                return INVALID_SCHEMA
            if not isinstance(obj.get("order_id"), str):
                return INVALID_SCHEMA
            return None

        if event_type == REPLACE:
            # Side and order type are inherited from the target, so the event
            # must not restate them; time-in-force is always GTC.
            if not keys >= _REQUIRED_REPLACE_KEYS:
                return INVALID_SCHEMA
            if not keys <= _ALLOWED_REPLACE_KEYS:
                return INVALID_SCHEMA
            if not isinstance(obj.get("order_id"), str):
                return INVALID_SCHEMA
            if not _is_positive_int(obj.get("quantity")):
                return INVALID_SCHEMA
            if not _is_positive_int(obj.get("price")):
                return INVALID_SCHEMA
            if "display_quantity" in obj:
                display_quantity = obj["display_quantity"]
                if (
                    not _is_positive_int(display_quantity)
                    or display_quantity > obj["quantity"]
                ):
                    return INVALID_SCHEMA
            return None

        if event_type != ADD:
            return INVALID_SCHEMA
        if not keys >= _REQUIRED_ADD_KEYS:
            return INVALID_SCHEMA

        if not isinstance(obj.get("order_id"), str):
            return INVALID_SCHEMA
        if obj.get("side") not in (BUY, SELL):
            return INVALID_SCHEMA
        order_type = obj.get("order_type")
        if order_type not in (LIMIT, MARKET, ICEBERG):
            return INVALID_SCHEMA
        if not _is_positive_int(obj.get("quantity")):
            return INVALID_SCHEMA
        if "account_id" in obj and not (
            isinstance(obj.get("account_id"), str) and obj["account_id"] != ""
        ):
            # The account tag is optional but may only be a non-empty string.
            return INVALID_SCHEMA
        if order_type != ICEBERG and "display_quantity" in obj:
            # Only iceberg orders carry a display slice size.
            return INVALID_SCHEMA

        if order_type == ICEBERG:
            # Iceberg orders are always-priced GTC limit orders whose single
            # maximum visible slice must not exceed the total quantity.
            if not _is_positive_int(obj.get("price")):
                return INVALID_SCHEMA
            display_quantity = obj.get("display_quantity")
            if not _is_positive_int(display_quantity) or display_quantity > obj["quantity"]:
                return INVALID_SCHEMA
            tif = obj.get("time_in_force")
            if "time_in_force" in obj and tif != GTC:
                # Only an omitted field or explicit GTC are accepted.
                return INVALID_SCHEMA
            return None

        if "price" in obj:
            price = obj["price"]
            if order_type == LIMIT:
                if not _is_positive_int(price):
                    return INVALID_SCHEMA
            elif price is not None:
                # MARKET orders must not carry a non-null price.
                return INVALID_SCHEMA
        elif order_type == LIMIT:
            return INVALID_SCHEMA

        if "time_in_force" in obj:
            tif = obj["time_in_force"]
            if tif not in (GTC, IOC, FOK):
                # Non-string values and unknown time-in-force values.
                return INVALID_SCHEMA
            if order_type == MARKET and tif == GTC:
                return INVALID_SCHEMA

        return None

    def _books(self, side: str) -> tuple[dict[int, deque[str]], dict[int, int]]:
        """The book and visible totals on which ``side`` rests."""
        if side == BUY:
            return self._bids, self._bid_totals
        return self._asks, self._ask_totals

    def _opposite(self, side: str) -> tuple[dict[int, deque[str]], dict[int, int]]:
        """The book and visible totals against which ``side`` matches."""
        if side == BUY:
            return self._asks, self._ask_totals
        return self._bids, self._bid_totals

    @staticmethod
    def _tradable_fn(side: str, limit: int | None):
        if side == BUY:
            def tradable(price: int) -> bool:
                return limit is None or price <= limit
        else:
            def tradable(price: int) -> bool:
                return limit is None or price >= limit
        return tradable

    def _add(
        self, event_id: str, obj: dict[str, object]
    ) -> tuple[str, str, str | None, list[dict[str, object]], dict[str, object] | None]:
        order_id: str = obj["order_id"]
        if order_id in self._order_ids or order_id in self._reserved_order_ids:
            return event_id, REJECTED, DUPLICATE_ORDER_ID, [], None
        self._order_ids.add(order_id)

        side: str = obj["side"]
        order_type: str = obj["order_type"]
        quantity: int = obj["quantity"]
        remaining: int = quantity
        is_iceberg = order_type == ICEBERG
        limit: int | None = obj["price"] if order_type in (LIMIT, ICEBERG) else None
        # LIMIT/ICEBERG default to GTC; MARKET keeps its historical
        # immediate-or-cancel semantics. MARKET with explicit GTC and ICEBERG
        # with any other time-in-force are rejected during schema checks.
        tif: str = obj.get("time_in_force") or (
            GTC if order_type in (LIMIT, ICEBERG) else IOC
        )
        display_quantity: int | None = (
            obj["display_quantity"] if is_iceberg else None
        )
        account_id: str | None = obj.get("account_id")
        if account_id is not None:
            # Any accepted ADD makes its account known, regardless of how the
            # order itself ends up.
            self._accounts.add(account_id)

        # FOK must either match the whole quantity against the pre-event book
        # or do nothing at all: no trades, no book change, no trade ids spent.
        # The precheck walks the book in the same price-time order a real fill
        # would; a resting iceberg offers its full remaining quantity here,
        # including reserve that is not part of the visible book totals. A
        # same-account resting order reached before the quantity is met aborts
        # the event atomically, before any trade could occur.
        if tif == FOK:
            fok = self._fok_probe(side, limit, quantity, account_id)
            if fok is not None:
                record: dict[str, object] = {
                    "side": side,
                    "price": limit,
                    "remaining": quantity,
                    "status": CANCELLED,
                }
                if account_id is not None:
                    record["account_id"] = account_id
                self._orders[order_id] = record
                if fok is False:
                    return event_id, UNFILLED_CANCELLED, None, [], None
                stp = {
                    "maker_order_id": fok,
                    "taker_order_id": order_id,
                    "cancelled_quantity": quantity,
                }
                return event_id, SELF_TRADE_PREVENTED, None, [], stp

        remaining, trades, stp_maker = self._match(
            event_id, order_id, side, limit, remaining, account_id
        )

        record = {"side": side, "price": limit}
        if account_id is not None:
            record["account_id"] = account_id
        stp: dict[str, object] | None = None
        if stp_maker is not None:
            # The whole leftover is cancelled; the blocking passive order is
            # neither traded nor displaced, and no later liquidity is sought.
            result = (
                PARTIALLY_FILLED_SELF_TRADE_PREVENTED if trades else SELF_TRADE_PREVENTED
            )
            record["remaining"] = remaining
            record["status"] = CANCELLED
            stp = {
                "maker_order_id": stp_maker,
                "taker_order_id": order_id,
                "cancelled_quantity": remaining,
            }
        elif remaining == 0:
            result = FILLED
            record["remaining"] = 0
            record["status"] = FILLED
        elif order_type in (LIMIT, ICEBERG) and tif == GTC:
            result = PARTIALLY_FILLED_RESTING if trades else RESTING
            record["remaining"] = remaining
            record["status"] = RESTING
            self._rest(
                order_id, side, limit, remaining,
                display_quantity if is_iceberg else None, record,
            )
        else:
            # IOC leftovers never enter the book; a successful FOK is always
            # fully filled by construction of the pre-event availability check.
            result = PARTIALLY_FILLED_CANCELLED if trades else UNFILLED_CANCELLED
            record["remaining"] = remaining
            record["status"] = CANCELLED

        self._orders[order_id] = record
        return event_id, result, None, trades, stp

    def _fok_probe(
        self, side: str, limit: int | None, quantity: int, account_id: str | None
    ) -> str | bool | None:
        """Probe a FOK request against the pre-event book without mutating it.

        Returns ``None`` when the whole quantity can be filled, ``False`` when
        liquidity runs short, or the id of the first same-account resting order
        reached before the quantity could be met. The walk mirrors a real fill:
        price-time priority across and within levels, and an exhausted iceberg
        slice replenishes at the tail of its level (including the hidden
        reserve) before the level is drained. Queues and slice sizes are copied
        for the simulation so the live book stays untouched.
        """
        opposite, _totals = self._opposite(side)
        tradable = self._tradable_fn(side, limit)
        need = quantity
        prices = sorted(opposite, reverse=side == SELL)
        for price in prices:
            if not tradable(price):
                continue
            sim_remaining: dict[str, int] = {}
            sim_visible: dict[str, int] = {}
            queue: deque[str] = deque()
            for maker_id in opposite[price]:
                maker = self._orders[maker_id]
                sim_remaining[maker_id] = maker["remaining"]
                if maker.get("visible") is not None:
                    sim_visible[maker_id] = maker["visible"]
                queue.append(maker_id)
            while queue and need > 0:
                maker_id = queue.popleft()
                maker = self._orders[maker_id]
                if account_id is not None and maker.get("account_id") == account_id:
                    return maker_id
                if maker_id in sim_visible:
                    available = sim_visible[maker_id]
                else:
                    available = sim_remaining[maker_id]
                need -= available
                sim_remaining[maker_id] -= available
                if maker_id in sim_visible:
                    sim_visible[maker_id] -= available
                    if sim_visible[maker_id] == 0 and sim_remaining[maker_id] > 0:
                        # The replenished slice waits behind every order already
                        # visible at this level, exactly as in a real fill.
                        sim_visible[maker_id] = min(
                            maker["display_quantity"], sim_remaining[maker_id]
                        )
                        queue.append(maker_id)
            if need <= 0:
                return None
        return False

    def _match(
        self,
        event_id: str,
        order_id: str,
        side: str,
        limit: int | None,
        remaining: int,
        account_id: str | None,
    ) -> tuple[int, list[dict[str, object]], str | None]:
        """Match ``order_id`` as taker.

        Returns its leftover, the trades already produced, and the id of the
        first same-account passive order reached (``None`` when matching ended
        normally). On a self-trade block no further liquidity is consulted and
        the blocking order is left exactly as it was.
        """
        opposite, totals = self._opposite(side)
        tradable = self._tradable_fn(side, limit)

        trades: list[dict[str, object]] = []
        blocked_by: str | None = None
        while remaining > 0:
            candidates = [price for price in totals if tradable(price)]
            if not candidates:
                break
            price = min(candidates) if side == BUY else max(candidates)
            queue = opposite[price]
            while remaining > 0 and queue:
                maker_id = queue[0]
                maker = self._orders[maker_id]
                if account_id is not None and maker.get("account_id") == account_id:
                    # No trade, no queue/remaining/slice change; the taker
                    # leftover is cancelled by the caller without skipping on.
                    blocked_by = maker_id
                    return remaining, trades, blocked_by
                if maker.get("visible") is not None:
                    # A resting iceberg can only trade its current slice; the
                    # reserve stays hidden until the slice is exhausted.
                    maker_available = maker["visible"]
                else:
                    maker_available = maker["remaining"]
                matched = min(remaining, maker_available)
                maker["remaining"] -= matched
                remaining -= matched
                totals[price] -= matched
                trade: dict[str, object] = {
                    "trade_id": self._next_trade_id,
                    "maker_order_id": maker_id,
                    "taker_order_id": order_id,
                    "price": price,
                    "quantity": matched,
                }
                trades.append(trade)
                self._trade_log.append({**trade, "event_id": event_id})
                self._next_trade_id += 1
                if maker.get("visible") is not None:
                    maker["visible"] -= matched
                    if maker["visible"] == 0:
                        # The slice leaves the front immediately. With reserve
                        # left, the next slice joins behind every order already
                        # visible at this price, so this same taker may meet the
                        # order again after those orders.
                        queue.popleft()
                        if maker["remaining"] > 0:
                            new_slice = min(
                                maker["display_quantity"], maker["remaining"]
                            )
                            maker["visible"] = new_slice
                            totals[price] += new_slice
                            queue.append(maker_id)
                        else:
                            maker["status"] = FILLED
                elif maker["remaining"] == 0:
                    queue.popleft()
                    maker["status"] = FILLED
            if not queue:
                del opposite[price]
                del totals[price]
        return remaining, trades, blocked_by

    def _rest(
        self,
        order_id: str,
        side: str,
        limit: int,
        remaining: int,
        display_quantity: int | None,
        record: dict[str, object],
    ) -> None:
        """Enter the leftover at the back of its price level's queue."""
        own_book, own_totals = self._books(side)
        own_book.setdefault(limit, deque()).append(order_id)
        if display_quantity is not None:
            # Only the first slice enters the book; the rest is reserve.
            visible = min(display_quantity, remaining)
            record["display_quantity"] = display_quantity
            record["visible"] = visible
        else:
            visible = remaining
        own_totals[limit] = own_totals.get(limit, 0) + visible

    def _remove_from_book(self, order_id: str, record: dict[str, object]) -> None:
        """Remove a resting order's visible quantity from its price level."""
        own_book, own_totals = self._books(record["side"])
        price = record["price"]
        queue = own_book[price]
        queue.remove(order_id)
        # Book totals hold only the current visible slice of an iceberg; its
        # reserve leaves with the order but was never aggregated.
        visible = record.get("visible", record["remaining"])
        own_totals[price] -= visible
        if own_totals[price] == 0:
            del own_totals[price]
            del own_book[price]

    def _replace(
        self, event_id: str, obj: dict[str, object]
    ) -> tuple[str, str, str | None, list[dict[str, object]], dict[str, object] | None]:
        order_id: str = obj["order_id"]
        record = self._orders.get(order_id)
        if record is None or record["status"] != RESTING:
            return event_id, REJECTED, UNKNOWN_ORDER, [], None

        side: str = record["side"]
        # The replacement trades under the target's account; the event itself
        # is forbidden from carrying account_id by the schema checks.
        account_id: str | None = record.get("account_id")
        is_iceberg = "display_quantity" in record
        display_quantity = obj.get("display_quantity")
        if display_quantity is None:
            # An omitted slice size keeps the target's original peak.
            display_quantity = record.get("display_quantity")

        # Removal, matching and re-resting are one indivisible state change:
        # the old remainder leaves the book before the replacement arrives,
        # so the new order can never trade against its own previous state.
        self._remove_from_book(order_id, record)

        price: int = obj["price"]
        remaining, trades, stp_maker = self._match(
            event_id, order_id, side, price, obj["quantity"], account_id
        )

        new_record: dict[str, object] = {"side": side, "price": price}
        if account_id is not None:
            new_record["account_id"] = account_id
        stp: dict[str, object] | None = None
        if stp_maker is not None:
            # The old remainder was already removed and is not restored; the
            # replacement is cancelled with whatever it had left.
            result = (
                PARTIALLY_FILLED_SELF_TRADE_PREVENTED if trades else SELF_TRADE_PREVENTED
            )
            new_record["remaining"] = remaining
            new_record["status"] = CANCELLED
            stp = {
                "maker_order_id": stp_maker,
                "taker_order_id": order_id,
                "cancelled_quantity": remaining,
            }
        elif remaining == 0:
            result = FILLED
            new_record["remaining"] = 0
            new_record["status"] = FILLED
        else:
            # The replacement is a fresh GTC arrival and always rests.
            result = PARTIALLY_FILLED_RESTING if trades else REPLACED
            new_record["remaining"] = remaining
            new_record["status"] = RESTING
            self._rest(
                order_id, side, price, remaining,
                display_quantity if is_iceberg else None, new_record,
            )

        # The order id stays occupied: the replacement keeps it and no later
        # ADD may reuse it.
        self._orders[order_id] = new_record
        return event_id, result, None, trades, stp

    def _cancel(
        self, event_id: str, order_id: str
    ) -> tuple[str, str, str | None, list[dict[str, object]]]:
        record = self._orders.get(order_id)
        if record is None or record["status"] != RESTING:
            return event_id, REJECTED, UNKNOWN_ORDER, []

        self._remove_from_book(order_id, record)
        record["status"] = CANCELLED
        record["remaining"] = 0
        return event_id, CANCELLED, None, []

    def _execution_report(
        self, event_id: str, obj: dict[str, object]
    ) -> tuple[
        str, str, str | None,
        list[dict[str, object]], dict[str, object] | None, dict[str, object] | None,
    ]:
        """Answer a cumulative execution query without touching any state.

        Every trade the order ever took part in is attributed to its original
        ``order_id``: replacements keep the id and iceberg replenishment slices
        trade under the same maker id, so the journal lookup alone gathers the
        full history, whether the order acted as maker or taker.
        """
        order_id: str = obj["order_id"]
        record = self._orders.get(order_id)
        if record is None:
            return event_id, REJECTED, UNKNOWN_ORDER, [], None, None

        side: str = record["side"]
        status: str = record["status"]
        # A resting order's remaining total includes the iceberg reserve; a
        # finished order has nothing open.
        open_quantity = record["remaining"] if status == RESTING else 0

        attribution: list[dict[str, object]] = []
        filled_quantity = 0
        executed_notional = 0
        for trade in self._trade_log:
            if trade["maker_order_id"] == order_id:
                role = MAKER
                counterparty = trade["taker_order_id"]
            elif trade["taker_order_id"] == order_id:
                role = TAKER
                counterparty = trade["maker_order_id"]
            else:
                continue
            filled_quantity += trade["quantity"]
            executed_notional += trade["price"] * trade["quantity"]
            attribution.append(
                {
                    "trade_id": trade["trade_id"],
                    "role": role,
                    "counterparty_order_id": counterparty,
                    "event_id": trade["event_id"],
                    "price": trade["price"],
                    "quantity": trade["quantity"],
                }
            )

        if filled_quantity:
            vwap: dict[str, int] | None = {
                "numerator": executed_notional,
                "denominator": filled_quantity,
            }
        else:
            vwap = None
        benchmark_price: int = obj["benchmark_price"]
        slippage = executed_notional - benchmark_price * filled_quantity
        if side == SELL:
            # Mirror the buy formula: negative always means improvement.
            slippage = -slippage

        analysis: dict[str, object] = {
            "side": side,
            "current_status": status,
            "open_quantity": open_quantity,
            "filled_quantity": filled_quantity,
            "executed_notional": executed_notional,
            "vwap": vwap,
            "slippage_notional": slippage,
            "trade_attribution": attribution,
        }
        return event_id, REPORTED, None, [], None, analysis

    def _impact_report(
        self, event_id: str, obj: dict[str, object]
    ) -> tuple[str, str, None, list[dict[str, object]], dict[str, object]]:
        """Estimate an anonymous MARKET order's execution without any mutation.

        The simulation walks the opposite book in strict price-time priority,
        trades at maker prices and consumes an iceberg's current visible slice
        before any reserve; an exhausted slice with reserve left replenishes at
        the tail of its price level, exactly like a real fill. The simulated
        order is anonymous and unrestricted, so self-trade prevention never
        applies and every visible price level is consumed until the requested
        quantity is met or liquidity runs out. It produces no trades and
        leaves the book, queues, orders, iceberg slices, trade journal,
        accounts and the next trade id untouched.
        """
        side: str = obj["side"]
        requested_quantity: int = obj["quantity"]
        benchmark_price: int = obj["benchmark_price"]

        fills, executable_quantity, executed_notional = self._simulate_market(
            side, requested_quantity
        )
        unfilled_quantity = requested_quantity - executable_quantity
        if executable_quantity:
            best_price: int | None = fills[0][0]
            vwap: dict[str, int] | None = {
                "numerator": executed_notional,
                "denominator": executable_quantity,
            }
            # Slippage against the caller's benchmark; impact against the
            # pre-query best opposite price. The sell side mirrors the buy
            # formula so a negative value always means improvement.
            slippage = executed_notional - benchmark_price * executable_quantity
            impact = executed_notional - best_price * executable_quantity
            if side == SELL:
                slippage = -slippage
                impact = -impact
        else:
            best_price = None
            vwap = None
            slippage = 0
            impact = 0

        analysis: dict[str, object] = {
            "side": side,
            "requested_quantity": requested_quantity,
            "benchmark_price": benchmark_price,
            "executable_quantity": executable_quantity,
            "unfilled_quantity": unfilled_quantity,
            "executed_notional": executed_notional,
            "best_price": best_price,
            "vwap": vwap,
            "slippage_notional": slippage,
            "impact_notional": impact,
            "price_breakdown": [
                {"price": price, "quantity": quantity}
                for price, quantity in fills
            ],
        }
        return event_id, REPORTED, None, [], analysis

    def _simulate_market(
        self, side: str, quantity: int
    ) -> tuple[list[tuple[int, int]], int, int]:
        """Walk the opposite book as an anonymous market order on a copy.

        Returns ``(fills, executable_quantity, executed_notional)`` where
        ``fills`` holds one ``(price, quantity)`` entry per simulated fill, in
        simulation order: one entry for each passive visible slice consumed,
        exactly the granularity real trades have (so a replenished iceberg
        contributes several entries, interleaved with same-price makers ahead
        of its tail-replenished slices). Queues, remainders and iceberg slices
        are copied into local structures so the live book stays untouched.
        """
        opposite, _totals = self._opposite(side)
        # A buy takes the lowest asks first; a sell takes the highest bids.
        prices = sorted(opposite, reverse=side == SELL)
        need = quantity
        fills: list[tuple[int, int]] = []
        for price in prices:
            if need == 0:
                break
            sim_remaining: dict[str, int] = {}
            sim_visible: dict[str, int] = {}
            queue: deque[str] = deque()
            for maker_id in opposite[price]:
                maker = self._orders[maker_id]
                sim_remaining[maker_id] = maker["remaining"]
                if maker.get("visible") is not None:
                    sim_visible[maker_id] = maker["visible"]
                queue.append(maker_id)
            while queue and need > 0:
                maker_id = queue.popleft()
                maker = self._orders[maker_id]
                if maker_id in sim_visible:
                    # A resting iceberg only offers its current slice first.
                    available = sim_visible[maker_id]
                else:
                    available = sim_remaining[maker_id]
                matched = min(need, available)
                need -= matched
                sim_remaining[maker_id] -= matched
                fills.append((price, matched))
                if maker_id in sim_visible:
                    sim_visible[maker_id] -= matched
                    if sim_visible[maker_id] == 0 and sim_remaining[maker_id] > 0:
                        # The replenished slice waits behind every order still
                        # visible at this level, exactly as in a real fill.
                        sim_visible[maker_id] = min(
                            maker["display_quantity"], sim_remaining[maker_id]
                        )
                        queue.append(maker_id)
        executable_quantity = quantity - need
        executed_notional = sum(price * qty for price, qty in fills)
        return fills, executable_quantity, executed_notional

    def knows_account(self, account_id: str) -> bool:
        """Whether an accepted ADD ever named ``account_id``.

        Orders keep their account however they ended up (resting, filled or
        cancelled); rejected ADDs never reach the account set. Used by the
        multi-symbol replay layer's cross-security portfolio query.
        """
        return account_id in self._accounts

    def known_accounts(self) -> list[str]:
        """Every account an accepted ADD on this security ever named.

        The set is independent of later order outcomes: an account whose
        orders were cancelled or never traded is still known. Used by the
        multi-symbol replay layer's whole-session reconciliation, which also
        reports accounts with zero trades.
        """
        return list(self._accounts)

    def trade_history(self) -> list[dict[str, object]]:
        """Every trade ever executed on this security, in trade_id order.

        Each entry carries the internal ``event_id`` tag in addition to the
        public trade fields; the replay-layer reconciliation projects the
        public fields out when comparing against external records. The
        returned list is a deep copy, so callers can never mutate the journal.
        """
        return copy.deepcopy(self._trade_log)

    def account_aggregates(
        self, account_id: str
    ) -> tuple[int, int, int, int]:
        """Cumulative traded quantities and notionals for one account.

        Returns ``(buy_quantity, sell_quantity, buy_notional, sell_notional)``
        accumulated from every trade the account's orders took part in as maker
        or taker on this engine's security. Replacements keep the order id and
        its account, and iceberg replenishment slices trade under the same
        maker id, so the journal lookup alone gathers the full history. Orders
        without an ``account_id`` never contribute.
        """
        buy_quantity = 0
        sell_quantity = 0
        buy_notional = 0
        sell_notional = 0
        for trade in self._trade_log:
            for order_key in ("maker_order_id", "taker_order_id"):
                order = self._orders[trade[order_key]]
                if order.get("account_id") != account_id:
                    continue
                notional = trade["price"] * trade["quantity"]
                if order["side"] == BUY:
                    buy_quantity += trade["quantity"]
                    buy_notional += notional
                else:
                    sell_quantity += trade["quantity"]
                    sell_notional += notional
        return buy_quantity, sell_quantity, buy_notional, sell_notional

    def _account_report(
        self, event_id: str, obj: dict[str, object]
    ) -> tuple[
        str, str, str | None,
        list[dict[str, object]], dict[str, object] | None,
        dict[str, object] | None, dict[str, object] | None,
    ]:
        """Answer a cumulative account query without touching any state.

        Every trade is attributed to an account through the order it was
        resting or arriving as: replacements keep the order id and its
        account, and iceberg replenishment slices trade under the same maker
        id, so the journal lookup alone gathers the full history. Orders
        without an ``account_id`` never contribute.
        """
        account_id: str = obj["account_id"]
        if not self.knows_account(account_id):
            return event_id, REJECTED, UNKNOWN_ACCOUNT, [], None, None, None

        buy_quantity, sell_quantity, buy_notional, sell_notional = (
            self.account_aggregates(account_id)
        )

        net_position = buy_quantity - sell_quantity
        if buy_quantity:
            buy_vwap: dict[str, int] | None = {
                "numerator": buy_notional,
                "denominator": buy_quantity,
            }
        else:
            buy_vwap = None
        if sell_quantity:
            sell_vwap: dict[str, int] | None = {
                "numerator": sell_notional,
                "denominator": sell_quantity,
            }
        else:
            sell_vwap = None

        mark_price: int = obj["mark_price"]
        analysis: dict[str, object] = {
            "account_id": account_id,
            "mark_price": mark_price,
            "buy_quantity": buy_quantity,
            "sell_quantity": sell_quantity,
            "net_position": net_position,
            "buy_notional": buy_notional,
            "sell_notional": sell_notional,
            "buy_vwap": buy_vwap,
            "sell_vwap": sell_vwap,
            "turnover_notional": buy_notional + sell_notional,
            "risk_exposure": abs(net_position) * mark_price,
            "mark_to_market_pnl": (
                sell_notional - buy_notional + net_position * mark_price
            ),
        }
        return event_id, REPORTED, None, [], None, None, analysis

    def _day_end_reconciliation(
        self, event_id: str, obj: dict[str, object]
    ) -> tuple[
        str, str, str | None,
        list[dict[str, object]], dict[str, object] | None,
        dict[str, object] | None, dict[str, object] | None,
        dict[str, object] | None,
    ]:
        """Compare the cumulative journal against external end-of-day records.

        Purely read-only: the book, order states, queue priorities, trade
        journal, account set and next trade id are all left untouched. The
        actual side is rebuilt from the same journal the reports use, so
        replacements and iceberg replenishment slices contribute under their
        original order id and inherited account.
        """
        actual_trades: dict[int, dict[str, object]] = {}
        for trade in self._trade_log:
            actual_trades[trade["trade_id"]] = {
                "trade_id": trade["trade_id"],
                "maker_order_id": trade["maker_order_id"],
                "taker_order_id": trade["taker_order_id"],
                "price": trade["price"],
                "quantity": trade["quantity"],
            }

        # Every account an accepted ADD ever named is part of the actual set,
        # whether or not it traded; cash is sell notional minus buy notional.
        actual_accounts: dict[str, dict[str, object]] = {
            account_id: {
                "account_id": account_id,
                "net_position": 0,
                "cash_balance": 0,
            }
            for account_id in self._accounts
        }
        for trade in self._trade_log:
            notional = trade["price"] * trade["quantity"]
            for order_key in ("maker_order_id", "taker_order_id"):
                order = self._orders[trade[order_key]]
                account_id = order.get("account_id")
                if account_id is None:
                    continue
                position = actual_accounts[account_id]
                if order["side"] == BUY:
                    position["net_position"] += trade["quantity"]
                    position["cash_balance"] -= notional
                else:
                    position["net_position"] -= trade["quantity"]
                    position["cash_balance"] += notional

        # The external records are normalized into the same field order the
        # actual side uses, so equal content compares (and serializes) equal.
        expected_trades: dict[int, dict[str, object]] = {}
        for item in obj["expected_trades"]:
            expected_trades[item["trade_id"]] = {
                "trade_id": item["trade_id"],
                "maker_order_id": item["maker_order_id"],
                "taker_order_id": item["taker_order_id"],
                "price": item["price"],
                "quantity": item["quantity"],
            }
        expected_accounts: dict[str, dict[str, object]] = {}
        for item in obj["expected_accounts"]:
            expected_accounts[item["account_id"]] = {
                "account_id": item["account_id"],
                "net_position": item["net_position"],
                "cash_balance": item["cash_balance"],
            }

        trade_breaks = self._reconcile_breaks(expected_trades, actual_trades)
        account_breaks = self._reconcile_breaks(expected_accounts, actual_accounts)
        result = RECONCILED if not trade_breaks and not account_breaks else BREAKS_FOUND
        reconciliation: dict[str, object] = {
            "trade_breaks": trade_breaks,
            "account_breaks": account_breaks,
        }
        return event_id, result, None, [], None, None, None, reconciliation

    @staticmethod
    def _reconcile_breaks(
        expected: dict[object, dict[str, object]],
        actual: dict[object, dict[str, object]],
    ) -> list[dict[str, object]]:
        """Full outer comparison of two identifier-keyed record sets.

        Breaks are emitted in ascending identifier order; a record present on
        only one side reports the other side as ``None``.
        """
        breaks: list[dict[str, object]] = []
        for identifier in sorted(expected.keys() | actual.keys()):
            exp = expected.get(identifier)
            act = actual.get(identifier)
            if exp is None:
                reason = MISSING_EXPECTED
            elif act is None:
                reason = MISSING_ACTUAL
            elif exp != act:
                reason = FIELD_MISMATCH
            else:
                continue
            breaks.append(
                {
                    "identifier": identifier,
                    "expected": exp,
                    "actual": act,
                    "reason": reason,
                }
            )
        return breaks

    def snapshot(self) -> tuple[list[dict[str, int]], list[dict[str, int]]]:
        bids = [
            {"price": price, "quantity": self._bid_totals[price]}
            for price in sorted(self._bid_totals, reverse=True)
        ]
        asks = [
            {"price": price, "quantity": self._ask_totals[price]}
            for price in sorted(self._ask_totals)
        ]
        return bids, asks

    def book_queue_view(
        self,
    ) -> tuple[list[dict[str, object]], list[dict[str, object]]]:
        """Project the current resting book into ordered queue levels.

        Bids are returned in descending price order and asks in ascending
        order; within a level orders keep their price-time queue priority.
        Each level carries its ``price``, the aggregate
        ``visible_quantity`` at that price and the queued ``orders``; every
        order carries its ``order_id``, ``order_type`` (``LIMIT`` or
        ``ICEBERG`` — only GTC limit and iceberg orders ever rest), its
        ``remaining_quantity`` (an iceberg's remainder still includes its
        hidden reserve) and its public ``visible_quantity`` (an iceberg's
        current slice only; a plain limit's whole remainder). Filled,
        cancelled or replaced orders are absent because they are not queued.
        Used solely by the replay layer's historical reconstruction query;
        it never mutates anything.
        """
        def project(book: dict[int, deque[str]], descending: bool):
            levels: list[dict[str, object]] = []
            for price in sorted(book, reverse=descending):
                orders: list[dict[str, object]] = []
                visible_quantity = 0
                for order_id in book[price]:
                    record = self._orders[order_id]
                    is_iceberg = record.get("visible") is not None
                    visible = record["visible"] if is_iceberg else record["remaining"]
                    visible_quantity += visible
                    orders.append({
                        "order_id": order_id,
                        "order_type": ICEBERG if is_iceberg else LIMIT,
                        "remaining_quantity": record["remaining"],
                        "visible_quantity": visible,
                    })
                levels.append({
                    "price": price,
                    "visible_quantity": visible_quantity,
                    "orders": orders,
                })
            return levels

        return project(self._bids, True), project(self._asks, False)

    def has_order_id(self, order_id: str) -> bool:
        """Whether an id is already spent or reserved by any accepted order."""
        return order_id in self._order_ids or order_id in self._reserved_order_ids

    def replace_target_kind(self, order_id: str) -> str | None:
        """Classify a REPLACE target without touching any state.

        Returns ``"iceberg"`` for a resting iceberg order, ``"plain"`` for any
        other resting order, or ``None`` when the id is unknown or finished
        (the baseline then rejects with ``UNKNOWN_ORDER``). Used solely by the
        multi-symbol replay layer to preserve the baseline precedence of the
        pre-commit rule that forbids a ``display_quantity`` on a plain target.
        """
        record = self._orders.get(order_id)
        if record is None or record["status"] != RESTING:
            return None
        return "iceberg" if "display_quantity" in record else "plain"

    def occupy_event_id(self, event_id: str) -> None:
        """Record a well-formed event id without processing any order event.

        Used solely by the multi-symbol replay layer's pre-matching business
        rejections (a static price-limit breach is decided before this engine
        is dispatched, yet the rejected event still occupies its id). The
        baseline JSON Lines entry point never calls this.
        """
        self._event_ids.add(event_id)

    def reserve_order_id(self, order_id: str) -> None:
        """Block an id from external ADD before its derived order is submitted.

        Used by parent-order plans: every future slice id is reserved when the
        plan starts, so a later external ADD can never occupy it. Releasing the
        slice moves the id into the regular spent-id set.
        """
        self._reserved_order_ids.add(order_id)

    def release_order_id(self, order_id: str) -> None:
        """Clear a reservation immediately before the derived order is added.

        The subsequent ADD then spends the id through the regular path.
        """
        self._reserved_order_ids.discard(order_id)

    def level_totals(self) -> tuple[dict[int, int], dict[int, int]]:
        """Raw visible-quantity aggregates keyed by price (bid, then ask)."""
        return self._bid_totals, self._ask_totals

    def dump_state(self) -> dict[str, object]:
        """Export the complete mutable engine state for an authoritative owner.

        Containers are deep-copied so later processing cannot mutate the export.
        The state includes enough to preserve price-time queue priority, order
        remainders, iceberg slice/reserve bookkeeping, spent event/order ids,
        the cumulative trade journal and the next trade id counter.
        """
        return {
            "event_ids": set(self._event_ids),
            "order_ids": set(self._order_ids),
            "reserved_order_ids": set(self._reserved_order_ids),
            "orders": copy.deepcopy(self._orders),
            "bids": {p: deque(q) for p, q in self._bids.items()},
            "asks": {p: deque(q) for p, q in self._asks.items()},
            "bid_totals": dict(self._bid_totals),
            "ask_totals": dict(self._ask_totals),
            "next_trade_id": self._next_trade_id,
            "accounts": set(self._accounts),
            "trade_log": copy.deepcopy(self._trade_log),
        }

    def load_state(self, state: dict[str, object]) -> Engine:
        """Replace this engine's whole state from an authoritative export."""
        self._event_ids = set(state["event_ids"])
        self._order_ids = set(state["order_ids"])
        self._reserved_order_ids = set(state.get("reserved_order_ids", ()))
        self._orders = copy.deepcopy(state["orders"])
        self._bids = {p: deque(q) for p, q in state["bids"].items()}
        self._asks = {p: deque(q) for p, q in state["asks"].items()}
        self._bid_totals = dict(state["bid_totals"])
        self._ask_totals = dict(state["ask_totals"])
        self._next_trade_id = state["next_trade_id"]
        self._accounts = set(state["accounts"])
        self._trade_log = copy.deepcopy(state["trade_log"])
        return self

"""JSON Lines event replay over standard input/output.

Each non-empty input line is handled in order and produces one JSON object
on standard output. Empty lines are ignored. The program never opens any
files itself.
"""

from __future__ import annotations

import json
import sys

from .engine import Engine

_ERROR_IO = "ERROR_IO\n"


def _encode(payload: dict[str, object]) -> bytes:
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")


def replay(stdin: object = sys.stdin, stdout: object = sys.stdout, stderr: object = sys.stderr) -> int:
    """Run the replay loop. Returns the process exit code."""
    engine = Engine()
    out_parts: list[bytes] = []

    try:
        raw = stdin.buffer.read()
        text = raw.decode("utf-8")
    except (OSError, UnicodeError):
        try:
            stderr.write(_ERROR_IO)
            stderr.flush()
        except OSError:
            pass
        return 1

    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if line == "":
            continue

        event_id, result, reason, trades, stp, analysis, position, reconciliation, impact = (
            engine.handle_line_impact(line)
        )
        bids, asks = engine.snapshot()
        payload: dict[str, object] = {
            "input_line": line,
            "event_id": event_id,
            "result": result,
        }
        if reason is not None:
            payload["reason"] = reason
        if stp is not None:
            payload["self_trade_prevention"] = stp
        if analysis is not None:
            payload["execution_analysis"] = analysis
        if position is not None:
            payload["position_analysis"] = position
        if reconciliation is not None:
            payload["reconciliation"] = reconciliation
        if impact is not None:
            payload["impact_analysis"] = impact
        payload["trades"] = trades
        payload["bids"] = bids
        payload["asks"] = asks
        out_parts.append(_encode(payload))
        out_parts.append(b"\n")

    try:
        stdout.buffer.write(b"".join(out_parts))
        stdout.buffer.flush()
    except OSError:
        try:
            stderr.write(_ERROR_IO)
            stderr.flush()
        except OSError:
            pass
        return 1
    return 0

"""Single-document JSON entry point for ordered multi-symbol event replay.

The command reads exactly one UTF-8 JSON request document from standard
input and writes exactly one UTF-8 JSON response document to standard
output. It never opens files; snapshots and results only travel through the
caller-supplied document.
"""

from __future__ import annotations

import json
import sys

from .event_replay import (
    SnapshotError,
    canonical_json,
    replay_events,
)

_ERROR_IO = "ERROR_IO\n"
_INVALID_REQUEST = "INVALID_REQUEST"


def _write_error(stdout: object, stderr: object, code: str, message: str) -> int:
    try:
        stdout.buffer.write(
            canonical_json({"error": {"code": code, "message": message}}) + b"\n"
        )
        stdout.buffer.flush()
    except OSError:
        try:
            stderr.write(_ERROR_IO)
            stderr.flush()
        except OSError:
            pass
        return 1
    return 2


def serve_events(
    stdin: object = sys.stdin,
    stdout: object = sys.stdout,
    stderr: object = sys.stderr,
) -> int:
    """Run one events request. Returns the process exit code."""
    try:
        raw = stdin.buffer.read()
        text = raw.decode("utf-8")
    except (OSError, UnicodeError):
        try:
            stderr.write(_ERROR_IO)
            stderr.flush()
        except OSError:
            pass
        return 1

    try:
        request = json.loads(text)
    except json.JSONDecodeError:
        return _write_error(stdout, stderr, _INVALID_REQUEST, "request must be one JSON document")
    if (
        not isinstance(request, dict)
        or not isinstance(request.get("events"), list)
        or not set(request) <= {"events", "config", "snapshot", "snapshot_after"}
        or (
            "config" in request
            and not isinstance(request["config"], dict)
        )
        or (
            "snapshot" in request
            and request["snapshot"] is not None
            and not isinstance(request["snapshot"], dict)
        )
    ):
        return _write_error(
            stdout, stderr, _INVALID_REQUEST,
            'request must be an object with an "events" list and optional '
            '"config" and "snapshot" objects',
        )

    marker = request.get("snapshot_after", "last")
    if marker is not None and marker != "last":
        if not (
            isinstance(marker, dict)
            and isinstance(marker.get("symbol"), str)
            and isinstance(marker.get("sequence"), int)
        ):
            return _write_error(
                stdout, stderr, _INVALID_REQUEST,
                'snapshot_after must be "last", null or '
                '{"symbol": str, "sequence": int}',
            )

    try:
        response = replay_events(
            request["events"],
            config=request.get("config"),
            snapshot=request.get("snapshot"),
            snapshot_after=marker,
        )
    except SnapshotError as exc:
        return _write_error(stdout, stderr, exc.code, str(exc))
    except (TypeError, ValueError) as exc:
        return _write_error(stdout, stderr, _INVALID_REQUEST, str(exc))

    try:
        stdout.buffer.write(canonical_json(response) + b"\n")
        stdout.buffer.flush()
    except OSError:
        try:
            stderr.write(_ERROR_IO)
            stderr.flush()
        except OSError:
            pass
        return 1
    return 0

