            symbol = event["symbol"]
            old_to_new[(symbol, event["sequence"])] = new_seq[symbol]
            new_seq[symbol] += 1

        cleaned = []
        next_sequence = {s: 1 for s in SYMBOLS}
        for event, is_committed in zip(self.events, self.committed):
            if not is_committed:
